module and_or_not(y, a, b, rsb);
    output y;
    input a, b, rsb;

    reg yi;

    always @(a or b or rsb) begin
        if (rsb == 0) begin
            yi <= 1;
        end
        else if (a & b) begin
            yi <= 1;
        end
        else if (a == 0 & b == 0) begin
            yi <= 0;
        end
        else begin
            yi <= x;
        end
    end

    assign #1 y = yi;
endmodule

