    if (!reset) begin
      bor_ff <= 0;
    end else begin
      if (Vin < Vth) begin
        bor_ff <= 1;
      end else begin
        bor_ff <= 0;
      end
    end
  end

  assign rst_out = bor_ff;

endmodule

