module Problem4(
    input A,
    input B,
    input GTI,
    input LTI,
    input EQI,
    output reg GTO,
    output reg LTO,
    output reg EQO
    );

    always @(*) begin
        if (A > B) begin
            GTO = 1;
            LTO = 0;
            EQO = 0;
        end else if (A < B) begin
            GTO = 0;
            LTO = 1;
            EQO = 0;
        end else begin
            GTO = 0;
            LTO = 0;
            EQO = 1;
        end
    end

    initial begin
        GTO = GTI;
        LTO = LTI;
        EQO = EQI;
    end

endmodule

