  input [data_width-1:0] data,
  input we,
  output reg [data_width-1:0] out
);

  parameter addr_width = 8;
  parameter data_width = 8;
  parameter mem_depth = 2**addr_width;

  reg [data_width-1:0] Mem [0:mem_depth-1];

  always @(posedge clock) begin
    if (we) begin
      Mem[addr] <= data;
    end
    out <= Mem[addr];
  end

endmodule

