module pwm_generator (
  input clk,
  input [7:0] duty_cycle,
  output reg pwm
);

reg [31:0] counter = 0;

always @(posedge clk) begin
  if (counter < 200) begin
    pwm <= 1'b1;
  end else begin
    pwm <= 1'b0;
  end

  if (counter == 255) begin
    counter <= 0;
  end else begin
    counter <= counter + 1;
  end
end

always @(*) begin
  counter = (duty_cycle * 256) / 100;
end

endmodule

