module four_bit_adder_with_carry_input (
  input [3:0] A,
  input [3:0] B,
  input CIN,
  output [3:0] SUM,
  output COUT,
  input VDD,
  input VSS
);

  wire [3:0] sum;
  wire cout;

  assign sum = A + B + CIN;
  assign COUT = (sum > 4'b1111);

  sky130_fd_sc_hd__mux_2 mux0 (
    .A(sum),
    .B(4'b0000),
    .S(COUT),
    .Y(SUM)
  );

endmodule

module ripple_carry_adder (
  input [3:0] a, b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] c;

  assign c[0] = cin;
  assign c[1] = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);
  assign c[2] = (a[1] & b[1]) | (a[1] & c[1]) | (b[1] & c[1]);
  assign c[3] = (a[2] & b[2]) | (a[2] & c[2]) | (b[2] & c[2]);

  assign sum = a + b + cin;
  assign cout = c[3];

endmodule

