module four_bit_adder(
    input [3:0] A,
    input [3:0] B,
    output reg [4:0] Y
);

    wire co1, co2, co3;
    sky130_fd_sc_lp__a311oi_lp a1(co1, A[0], B[0], 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0);
    sky130_fd_sc_lp__a311oi_lp a2(co2, A[1], B[1], co1, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0);
    sky130_fd_sc_lp__a311oi_lp a3(co3, A[2], B[2], co2, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0);
    sky130_fd_sc_lp__a311oi_lp a4(Y[4], A[3], B[3], co3, 1'b0, 1'b0, 1'b1, 1'b0, 1'b0, 1'b0);

    assign Y[3:0] = A[3:0] + B[3:0];

endmodule

