module shift_register (
    input [3:0] DATA,
    input SHIFT,
    input LOAD,
    output reg [3:0] Q
);

    always @ (posedge SHIFT or posedge LOAD)
    begin
        case (SHIFT)
            1'b0: Q <= {Q[2:0], Q[3]};
            1'b1: Q <= {Q[1:0], DATA[3:2]};
        endcase

        if (LOAD)
            Q <= DATA;
    end

endmodule

module d_ff_async_reset_set (
    input D,
    input CLK,
    input RESET,
    input SET,
    output Q,
    output Q_N
);

    reg Q;
    wire Q_N;

    assign Q_N = ~Q;

    always @(posedge CLK or negedge RESET or negedge SET) begin
        if (!RESET) begin
            Q <= 0;
        end else if (!SET) begin
            Q <= 1;
        end else begin
            Q <= D;
        end
    end

endmodule

