module dflipflop (
    input D,
    input clk,
    input reset,
    output reg Q,
    output reg Q_n
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 0;
        Q_n <= 1;
    end else begin
        Q <= D;
        Q_n <= ~D;
    end
end

