module d_ff_arst (
    input CLK,
    input D,
    input SET_B,
    input RESET_B,
    output reg Q,
    output reg Q_N
);

    always @(posedge CLK or negedge SET_B or negedge RESET_B) begin
        if (!SET_B) begin
            Q <= 1;
            Q_N <= 0;
        end else if (!RESET_B) begin
            Q <= 0;
            Q_N <= 1;
        end else begin
            Q <= D;
            Q_N <= ~D;
        end
    end

endmodule

module bin_to_gray(clk, reset, bin_in, gray_out);

parameter DATA_WIDTH = 4;

input clk;
input reset;
input [DATA_WIDTH-1:0] bin_in;

output [DATA_WIDTH-1:0] gray_out;

reg [DATA_WIDTH-1:0] gray_out;

always @(posedge clk)
begin
    if(reset)
    begin
        gray_out <= 0;
    end
    else
    begin
        gray_out <= bin_in ^ (bin_in >> 1);
    end
end

endmodule

module counter_4bit(
  input clk, rst, en,
  output reg [3:0] out
);

  always @(posedge clk or negedge rst)
  begin
    if (!rst) // synchronous reset
      out <= 4'b0;
    else if (en) // asynchronous enable
      out <= out + 1;
  end

endmodule

