    assign sel1_inv = ~sel[1];

    always @(*) begin
        if (sel == 2'b00) begin
            out = in[0];
        end else if (sel == 2'b01) begin
            out = in[1];
        end else if (sel == 2'b10) begin
            out = in[2];
        end else begin
            out = in[3];
        end
    end

endmodule

